$('#annotation-form').onsubmit=async e=>{e.preventDefault();const text=$('#annotation-text').value.trim();if(!annotationTarget){toast('请先开启批注模式并点击一个组件。');return;}if(!text){toast('请写下批注意见。');return;}const now=new Date().toISOString();if(annotationEditing){const a=annotations.find(x=>x.id===annotationEditing);if(a){a.text=text;a.target=annotationTarget;a.context=annotationContext();a.updatedAt=now;}}else annotations.push({id:crypto.randomUUID(),text,target:annotationTarget,context:annotationContext(),createdAt:now,updatedAt:now,status:'open'});annotationEditing=null;annotationTarget=null;$('#annotation-text').value='';await persistAnnotations('批注已保存，可继续点击其他组件。');$('#annotation-panel').hidden=true;};
$('#annotation-list').onclick=async e=>{const action=e.target.closest('[data-ann-action]');if(!action)return;const item=action.closest('[data-annotation-id]'),a=annotations.find(x=>x.id===item.dataset.annotationId);if(!a)return;if(action.dataset.annAction==='delete'){annotations=annotations.filter(x=>x.id!==a.id);if(annotationEditing===a.id){annotationEditing=null;annotationTarget=null;$('#annotation-text').value='';}await persistAnnotations('批注已删除。');return;}const el=annotationElement(a);if(!el){toast('该批注位于其他页面或场景，请按记录切换后定位。');return;}el.scrollIntoView({behavior:'smooth',block:'center'});if(action.dataset.annAction==='edit')selectAnnotationTarget(el,a);else{el.animate([{outline:'4px solid #D97706'},{outline:'0 solid transparent'}],{duration:900});}};
$('#annotation-export').onclick=async()=>{const text=annotations.map((a,i)=>`${i+1}. [${a.context.route}/${a.context.scenario}/${a.context.theme}] ${a.target.label}\n${a.text}`).join('\n\n')||'暂无批注';try{await navigator.clipboard.writeText(text);toast('全部批注已复制。');}catch{const ta=document.createElement('textarea');ta.value=text;document.body.append(ta);ta.select();document.execCommand('copy');ta.remove();toast('全部批注已复制。');}};
